const QUEST_SCRIPT_ID = "quest.runtime";
export const STARTER_PRIEST_FETCH_QUEST_ID = "starter.priest_fetch";
export const STARTER_GRAVEYARD_QUEST_ID = STARTER_PRIEST_FETCH_QUEST_ID;
