    this.killer = Number(payload.killer || 0) | 0;
    this.cause = String(payload.cause || "");
    this.weaponId = Number(payload.weaponId || 0) | 0;
    this.weaponFamily = String(payload.weaponFamily || "");
    this.damageType = String(payload.damageType || "");
