    this.goreType = String(payload.goreType || "");
    this.sizeClass = String(payload.sizeClass || "");
    this.impactProfile = payload.impactProfile || null;
    this.targetKind = String(payload.targetKind || "");
    this.at = normalizeGridPoint(payload.at);

    Object.freeze(this);
